package checkout

import (
  "context"

  "go.opentelemetry.io/otel"
  "go.opentelemetry.io/otel/attribute"
)

var tracer = otel.Tracer("checkout")

type Service struct {
  carts    CartStore
  payments Payments
  orders   OrderStore
}

func (s *Service) PlaceOrder(ctx context.Context, cartID string) (string, error) {
  _, span := tracer.Start(ctx, "checkout.PlaceOrder")
  span.SetAttributes(attribute.String("cart.id", cartID))

  cart, err := s.carts.Load(ctx, cartID)
  if err != nil {
    return "", err
  }
  if err := s.payments.Charge(ctx, cart.Total); err != nil {
    return "", err
  }
  return s.orders.Create(ctx, cart)
}

