func (s *Service) PlaceOrder(ctx context.Context, cartID string) (string, error) {
  ctx, span := tracer.Start(ctx, "checkout.PlaceOrder")
  defer span.End()
  span.SetAttributes(attribute.String("cart.id", cartID))

  cart, err := s.carts.Load(ctx, cartID)
  if err != nil {
    return "", fail(span, err)
  }
  if err := s.payments.Charge(ctx, cart.Total); err != nil {
    return "", fail(span, err)
  }
  orderID, err := s.orders.Create(ctx, cart)
  if err != nil {
    return "", fail(span, err)
  }
  return orderID, nil
}

func fail(span trace.Span, err error) error {
  span.RecordError(err)
  return err
}

func fail(span trace.Span, err error) error {
  span.RecordError(err)
  span.SetStatus(codes.Error, err.Error())
  return err
}
